+/// Deletes this session's board, and with it every item and field it held.
+pub async fn delete(send: &impl Sender, board: &RunBoard) -> Result<(), String> {
+    let answer = send(
+        DELETE_BOARD_DOCUMENT,
+        "live board deletion",
+        json!({"input":{"projectId":board.id}}),
