+    account
+        .lock()
+        .unwrap()
+        .boards
+        .get_mut(&TEMPLATE)
+        .unwrap()
+        .items
+        .truncate(10);
+    let origin = serve(Arc::clone(&account));
+    let writes = |account: &Account| {
+        account
+            .seen
+            .iter()
+            .filter(|(_, document, _)| document.starts_with("mutation"))
+            .count()
+    };
+    let said = template_setup(&origin, "template-dry-run");
