+    assert_eq!(writes(&account.lock().unwrap()), 0, "a dry run wrote");
+    let said = template_setup(&origin, "template-fill");
+    assert!(
+        said.contains(&format!("added {} draft items", TEMPLATE_DRAFTS - 10)),
+        "{said}"
+    );
