+/// its message, and the message it presents naming the id.
+pub struct DuplicateIdRefusal {
+    pub code: &'static str,
+    pub message: &'static str,
+    pub presented: String,
+}
+
+/// [`DuplicateIdRefusal`] for `id`.
+#[must_use]
+pub fn duplicate_id_refusal(id: &str) -> DuplicateIdRefusal {
+    DuplicateIdRefusal {
+        code: "INPUT_ERROR",
+        message: "conflict on insert of Issue",
+        presented: format!("Entity Issue with id {id} already exists."),
+    }
