+
+/// Whether `error` is exactly `refusal`, every one of its three parts.
+fn refuses_the_duplicate(error: &Value, refusal: &DuplicateIdRefusal) -> bool {
+    error.pointer("/extensions/code").and_then(Value::as_str) == Some(refusal.code)
+        && error.get("message").and_then(Value::as_str) == Some(refusal.message)
+        && error
+            .pointer("/extensions/userPresentableMessage")
+            .and_then(Value::as_str)
+            == Some(refusal.presented.as_str())
